async function pull(){const r=await fetch('/api/workspace',{cache:'no-store'}),b=await r.json();if(!r.ok)throw new Error(b.error||'Could not load shared DCR records.');DB=b.state||{};WORKSPACE_REV=Number(b.revision||0);for(const k of ['pdc_register','pdc_status_history','dcr_log','audit_trail','dcr_records','dcr_collections','dcr_pdc_entries','dcr_deposits','cash_counts','dcr_checks'])if(!Array.isArray(DB[k]))DB[k]=[];SNAP=JSON.stringify(DB);LS.set('dcrdb',SNAP);st('☁ Shared records loaded · v'+WORKSPACE_REV)}
